package app.loveu;
import android.app.*;import android.content.*;import android.os.*;import java.util.concurrent.*;
/** User opted-in foreground relay checks; each network attempt is bounded. */
public final class CoupleBackgroundService extends Service {
 static final String OPEN="app.loveu.OPEN_COUPLE",CHANNEL="couple_background";static final int ID=21,NEW_ID=22;
 private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();static volatile java.util.function.Supplier<CoupleApi> emulatorApiFactory;
 static CoupleApi createApi(Context c){java.util.function.Supplier<CoupleApi> factory=emulatorApiFactory;return factory!=null&&(c.getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)!=0&&(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"))?factory.get():new CoupleApi();}
 private Future<?> task;private CoupleApi api;private boolean ended;
 public static void start(Context c){if(!CoupleBackgroundSync.enabled(c))return;CoupleBackgroundJob.schedule(c);try{c.startForegroundService(new Intent(c,CoupleBackgroundService.class));}catch(RuntimeException ignored){}}
 public static void stop(Context c){c.stopService(new Intent(c,CoupleBackgroundService.class));CoupleBackgroundJob.cancel(c);NotificationManager n=c.getSystemService(NotificationManager.class);if(n!=null)n.cancel(NEW_ID);}
 static Notification notification(Context c,String text,boolean ongoing){return notification(c,text,ongoing,ongoing?CHANNEL:"couple_updates");}
 static Notification notification(Context c,String text,boolean ongoing,String channel){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel(channel,Language.ui(ongoing?"双人连接":"双人空间更新"),ongoing?NotificationManager.IMPORTANCE_LOW:NotificationManager.IMPORTANCE_DEFAULT));Intent i=new Intent(c,MainActivity.class).setAction(OPEN).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);return new Notification.Builder(c,channel).setSmallIcon(android.R.drawable.ic_lock_lock).setContentTitle(Language.ui("Love U")).setContentText(Language.ui(text)).setVisibility(Notification.VISIBILITY_PRIVATE).setOngoing(ongoing).setAutoCancel(!ongoing).setContentIntent(PendingIntent.getActivity(c,21,i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build();}
 static void received(Context c,int ignored){receivedOnChannel(c,"couple_updates");}
 static void receivedOnChannel(Context c,String channel){try{synchronized(Vault.class){int count=CoupleBackgroundSync.pendingNotifications(c);if(count<=0||!CoupleBackgroundSync.enabled(c))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;NotificationManager manager=c.getSystemService(NotificationManager.class);Notification note=notification(c,"有新的双人空间更新，解锁后查看",false,channel);NotificationChannel updates=manager.getNotificationChannel(channel);if(!manager.areNotificationsEnabled()||updates==null||updates.getImportance()==NotificationManager.IMPORTANCE_NONE)return;manager.notify(NEW_ID,note);CoupleBackgroundSync.notificationDelivered(c,count);}}catch(Exception unavailable){}} public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int startId){if(ended){stopSelf();return START_NOT_STICKY;}startForeground(ID,notification(this,"后台加密连接已开启",true));if(!CoupleBackgroundSync.enabled(this)){finish();return START_NOT_STICKY;}if(task==null){handler.removeCallbacks(next);cycle();}return START_NOT_STICKY;}
 private int generation;
 private final Runnable next=()->cycle();
 private void cycle(){if(ended)return;if(!CoupleBackgroundSync.enabled(this)){finish();return;}final int run=++generation;api=createApi(this);final CoupleApi client=api;handler.postDelayed(deadline,20000);task=worker.submit(()->{int count=0;try{count=CoupleBackgroundSync.run(this,client);}catch(Exception ignored){}final int result=count;handler.post(()->{if(ended||run!=generation)return;received(this,result);endCycle();});});}
 private final Runnable deadline=()->endCycle();
 private void endCycle(){if(ended)return;received(this,0);generation++;handler.removeCallbacks(deadline);if(api!=null)api.cancel();if(task!=null)task.cancel(true);task=null;api=null;if(!CoupleBackgroundSync.enabled(this)){finish();return;}handler.removeCallbacks(next);handler.postDelayed(next,30000);}
 private void finish(){if(ended)return;ended=true;generation++;handler.removeCallbacks(deadline);handler.removeCallbacks(next);if(api!=null)api.cancel();if(task!=null)task.cancel(true);worker.shutdownNow();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 public void onDestroy(){finish();super.onDestroy();}
}